    headTail: "\n\n\n  <!-- Structured Data: Article -->\n  <script type=\"application/ld+json\">\n  {\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"Article\",\n    \"headline\": \"Swipe Left to Delete, Right to Keep: Organize Photos Fast\",\n    \"description\": \"Learn how to swipe left right to organize photos fast. Delete or keep images with a single gesture and clean up your iPhone library in minutes.\",\n    \"datePublished\": \"2026-06-13T00:00:00Z\",\n    \"dateModified\": \"2026-06-13\",\n    \"author\": {\n      \"@type\": \"Organization\",\n      \"name\": \"TidyByte\",\n      \"url\": \"https://tidybyte.360ghar.com\"\n    },\n    \"publisher\": {\n      \"@type\": \"Organization\",\n      \"name\": \"TidyByte\",\n      \"url\": \"https://tidybyte.360ghar.com\",\n      \"logo\": {\n        \"@type\": \"ImageObject\",\n        \"url\": \"https://tidybyte.360ghar.com/assets/img/icon-1024.png\",\n        \"width\": 1024,\n        \"height\": 1024\n      }\n    },\n    \"mainEntityOfPage\": {\n      \"@type\": \"WebPage\",\n      \"url\": \"https://tidybyte.360ghar.com/blog/swipe-left-right-organize-photos\"\n    },\n    \"image\": \"https://tidybyte.360ghar.com/assets/img/blog/swipe-left-right-organize-photos-og.jpg\"\n  }\n  </script>\n\n  <!-- Structured Data: FAQPage -->\n  <script type=\"application/ld+json\">\n  {\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FAQPage\",\n    \"mainEntity\": [\n      {\n        \"@type\": \"Question\",\n        \"name\": \"How do I swipe to organize photos?\",\n        \"acceptedAnswer\": {\n          \"@type\": \"Answer\",\n          \"text\": \"Open TidyByte's swipe view, which loads your camera roll by default. Each photo fills the screen. Swipe right to keep a photo, swipe left to mark it for deletion. The app immediately shows the next image so you can move through hundreds of photos in minutes without tapping menus or checkboxes.\"\n        }\n      },\n      {\n        \"@type\": \"Question\",\n        \"name\": \"What happens when I swipe left on a photo?\",\n        \"acceptedAnswer\": {\n          \"@type\": \"Answer\",\n          \"text\": \"A left swipe moves the photo to the Recently Deleted album inside iOS Photos. It is not permanently removed right away. iOS holds deleted photos for 30 days, giving you a safety window to recover anything removed by accident. TidyByte never bypasses this Apple-native trash flow.\"\n        }\n      },\n      {\n        \"@type\": \"Question\",\n        \"name\": \"Can I undo a swipe decision?\",\n        \"acceptedAnswer\": {\n          \"@type\": \"Answer\",\n          \"text\": \"Yes. TidyByte provides an undo button that reverts the most recent swipe action. You can also tap the photo to bring it back into full-screen view and reverse your choice. Since deleted photos go to the iOS Recently Deleted album, you can always recover them from within the Photos app during the 30-day window.\"\n        }\n      },\n      {\n        \"@type\": \"Question\",\n        \"name\": \"Can I choose which album to save to?\",\n        \"acceptedAnswer\": {\n          \"@type\": \"Answer\",\n          \"text\": \"When you swipe right to keep a photo, TidyByte can prompt you to assign it to a specific album. If you skip the prompt, the photo stays in your camera roll. Album assignment is optional, so power users who want full control can use it while anyone who prefers speed can skip it entirely.\"\n        }\n      },\n      {\n        \"@type\": \"Question\",\n        \"name\": \"Is there a swipe-based photo organizer?\",\n        \"acceptedAnswer\": {\n          \"@type\": \"Answer\",\n          \"text\": \"Yes. TidyByte is a free, open-source iOS app built around a swipe-based photo organizer interface. It runs entirely on your device with no account and no cloud upload. The swipe gesture maps to keep or delete, and you can process thousands of photos in a single session.\"\n        }\n      }\n    ]\n  }\n  </script>\n",
